const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

rl.on('line', (line) => {
    let n = parseInt(line.trim());

    let sum = 0n;
    let p = 1n;
    while (n > 0) {
        p *= 2n;
        sum += p;
        n--;
    }
    console.log(sum.toString());
    rl.close();
});
